const actions=[['☎','Call Aiko before consultation','Due 10:00','Open'],['◷','Day-14 check-in · Ito family','Overdue 1 day','Call'],['✓','Review Mugi’s care update','Assigned to you','Review'],['⌁','Approve two high-fit matches','Scored this morning','Open']];
const opportunities=[['Aiko Tanaka','Sora','Small dog · apartment','94'],['Yui Kobayashi','Mugi','Medium dog · experienced','91'],['Haruto Suzuki','Hana','Indoor cat · quiet home','89']];
const followups=[['D2','Aiko Tanaka','Day-2 wellbeing check','Due 09:30','Call'],['D14','Ito family','Behaviour and settling review','Overdue 1 day','LINE'],['D30','Haruto Suzuki','30-day outcome survey','Due 11:00','Email'],['D2','Yui Kobayashi','Medication confirmation','Due 13:30','Call'],['D90','Mei Nakamura','90-day outcome and referral','Due 15:00','LINE']];
const $=(s,c=document)=>c.querySelector(s),$$=(s,c=document)=>[...c.querySelectorAll(s)];let activeRecord=null,toastTimer,tourStep=0;
function rowMarkup(h,all=false){return `<tr data-stage="${h.stage}"><td><div class="person"><span class="person-avatar">${h.initials}</span><span><strong>${h.name}</strong><small>${h.id} · ${h.area}</small></span></div></td><td>${h.preference}</td>${all?`<td>${h.readiness}</td><td><span class="tag success">${h.contact}</span></td><td>${h.owner}</td><td>${h.activity}</td>`:`<td><span class="source"><i></i>${h.source}</span></td><td>${h.activity}</td><td><span class="stage ${h.stage}">${h.stageLabel}</span></td><td><span class="match-count">${h.matches} matches</span></td>`}<td><button class="open-record" data-record="${h.id}" aria-label="Open ${h.name}">›</button></td></tr>`}
function renderHouseholds(list=households){$('#household-rows').innerHTML=list.map(h=>rowMarkup(h)).join('');$('#all-households').innerHTML=households.map(h=>rowMarkup(h,true)).join('');bindRecordButtons()}
function bindRecordButtons(){$$('[data-record]').forEach(b=>b.onclick=()=>openRecord(b.dataset.record))}
function renderActions(){$('#action-list').innerHTML=actions.map((a,i)=>`<div class="action-item"><span class="action-icon">${a[0]}</span><span><strong>${a[1]}</strong><small>${a[2]}</small></span><button data-complete="${i}">${a[3]}</button></div>`).join('');$$('[data-complete]').forEach(b=>b.onclick=()=>{b.textContent='Done';b.closest('.action-item').style.opacity='.5';showToast('Task completed in the prototype.')})}
function renderOpportunities(){$('#opportunity-grid').innerHTML=opportunities.map((o,i)=>`<div class="opportunity" data-record="${households[i].id}"><div class="pair-photos"><span class="pet-photo">${households[i].initials}</span><span class="pet-photo">${o[1].slice(0,2).toUpperCase()}</span></div><span><strong>${o[0]} × ${o[1]}</strong><small>${o[2]}</small></span><span class="match-score" style="--score:${o[3]}"><b>${o[3]}%</b></span></div>`).join('');bindRecordButtons()}
function renderAnimals(){$('#animal-grid').innerHTML=animals.map(a=>`<article class="animal-card" data-action="animal-card"><div class="animal-visual"><span>${a.mark}</span><em>${a.status}</em></div><div class="animal-info"><h3>${a.name}</h3><p>${a.id} · ${a.type} · ${a.age} · ${a.sex}</p><div class="animal-meta"><span>Care note<br><b>${a.care}</b></span><span>Potential fits<br><b>${a.matches} households</b></span></div></div></article>`).join('')}
function renderKanban(){const columns=[['New suggestions',[[0,1,94],[1,2,89]]],['Staff review',[[2,0,91],[4,3,84]]],['Consultation',[[3,5,78],[0,0,76]]],['Reserved',[[1,6,93]]]];$('#match-kanban').innerHTML=columns.map(([title,cards])=>`<section class="kanban-column"><div class="kanban-head"><strong>${title}</strong><span>${cards.length}</span></div>${cards.map(([hi,ai,score])=>{const h=households[hi],a=animals[ai];return `<article class="match-card" data-record="${h.id}"><div class="match-card-top"><div class="person"><span class="person-avatar">${h.initials}</span><span><strong>${h.name}</strong><small>${h.area}</small></span></div><span class="score-badge">${score}% fit</span></div><div class="pairing"><span class="pet-photo">${a.mark}</span><span><strong>${a.name}</strong><small>${a.type} · ${a.age}</small></span></div><p>${score>90?'Strong home, timing and experience alignment.':'Good core fit; one staff review point remains.'}</p><div class="match-card-foot"><span>${h.id} × ${a.id}</span><span>${h.owner}</span></div></article>`}).join('')}</section>`).join('');bindRecordButtons()}
function renderFollowups(){$('#followup-list').innerHTML=followups.map((f,i)=>`<div class="followup-row"><span>${f[0]}</span><div><strong>${f[1]}</strong><small>${f[2]} · ${f[4]}</small></div><em>${f[3]}</em><button class="secondary" data-followup="${i}">Complete</button></div>`).join('');$$('[data-followup]').forEach(b=>b.onclick=()=>{b.textContent='Completed';b.disabled=true;b.closest('.followup-row').style.opacity='.5';showToast('Follow-up recorded with a timestamp.')})}
function setView(name){$$('.view').forEach(v=>v.classList.toggle('active',v.id===`view-${name}`));$$('.nav-link').forEach(n=>n.classList.toggle('active',n.dataset.viewLink===name));$('#sidebar').classList.remove('open');window.scrollTo({top:0});}
function openRecord(id){const h=households.find(x=>x.id===id)||households[0];activeRecord=h;$('#drawer-id').textContent=h.id;$('#drawer-name').textContent=h.name;$('#drawer-contact').textContent=`${h.area}, Tokyo · ${h.contact} preferred`;$('#drawer-stage').textContent=h.stageLabel;$('#drawer-profile').innerHTML=[['Looking for',h.preference],['Readiness',h.readiness],['Home',h.home],['Experience',h.experience],['Household',h.household],['Record owner',h.owner]].map(x=>`<div><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join('');const suggested=animals.slice(0,Math.min(h.matches,3));$('#drawer-matches').innerHTML=suggested.map((a,i)=>`<div class="drawer-match"><span class="pet-photo">${a.mark}</span><span><strong>${a.name} · ${a.type}</strong><small>${a.id} · ${a.care}</small></span><b>${94-i*5}%</b></div>`).join('');$('#drawer-timeline').innerHTML=[['Consultation booked','Today · 10:30'],['Preference and home details confirmed','Yesterday · '+h.owner],['Consent captured · '+h.contact,'2 days ago'],['Enquiry created · '+h.source,'2 days ago']].map(x=>`<div class="timeline-item"><strong>${x[0]}</strong><small>${x[1]}</small></div>`).join('');$('#record-drawer').classList.add('open');$('#drawer-backdrop').classList.add('open');$('#record-drawer').setAttribute('aria-hidden','false')}
function closeRecord(){$('#record-drawer').classList.remove('open');$('#drawer-backdrop').classList.remove('open');$('#record-drawer').setAttribute('aria-hidden','true')}
function showToast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2600)}
function openEnquiry(){$('#enquiry-modal').hidden=false;setTimeout(()=>$('#enquiry-form input').focus(),50)}function closeEnquiry(){$('#enquiry-modal').hidden=true}
$$('[data-view-link]').forEach(el=>el.addEventListener('click',e=>{e.preventDefault();setView(el.dataset.viewLink)}));$('#menu').onclick=()=>$('#sidebar').classList.toggle('open');$('#add-enquiry').onclick=openEnquiry;$$('[data-action="new-enquiry"]').forEach(b=>b.onclick=openEnquiry);$('#close-drawer').onclick=closeRecord;$('#drawer-backdrop').onclick=closeRecord;$('.modal-close').onclick=closeEnquiry;$('.modal-cancel').onclick=closeEnquiry;
$('#advance-stage').onclick=()=>{if(!activeRecord)return;const stages=[['new','New'],['qualified','Qualified'],['consultation','Consultation'],['matching','Matching']];let i=stages.findIndex(s=>s[0]===activeRecord.stage);i=Math.min(i+1,stages.length-1);activeRecord.stage=stages[i][0];activeRecord.stageLabel=stages[i][1];$('#drawer-stage').textContent=activeRecord.stageLabel;renderHouseholds();showToast(`Journey advanced to ${activeRecord.stageLabel}.`)};
$('#enquiry-form').addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.currentTarget),name=d.get('name');households.unshift({id:`HH-${2050+households.length}`,name,initials:name.split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase(),area:'Tokyo',contact:d.get('contact'),preference:d.get('preference'),source:d.get('source'),activity:'Just now',stage:'new',stageLabel:'New',matches:0,readiness:'To confirm',home:'To confirm',experience:'To confirm',household:'To confirm',owner:'K. Yen'});renderHouseholds();closeEnquiry();e.currentTarget.reset();setView('households');showToast('New enquiry created in this prototype session.')});
$$('.pipeline-tabs button').forEach(b=>b.onclick=()=>{$$('.pipeline-tabs button').forEach(x=>x.classList.remove('active'));b.classList.add('active');const stage=b.dataset.stage;renderHouseholds(stage==='all'?households:households.filter(h=>h.stage===stage))});
$('#search').addEventListener('input',e=>{const q=e.target.value.toLowerCase();if(q.length<2)return;const h=households.find(x=>(x.name+x.id+x.preference).toLowerCase().includes(q));if(h)openRecord(h.id)});$('#household-search').addEventListener('input',e=>{const q=e.target.value.toLowerCase();$('#all-households').innerHTML=households.filter(h=>(h.name+h.id+h.preference).toLowerCase().includes(q)).map(h=>rowMarkup(h,true)).join('');bindRecordButtons()});
document.addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(!a)return;const action=a.dataset.action;if(action==='sync')showToast('Website, LINE, ads, booking and POS are connected in the concept.');if(action==='brief')showToast('Daily operating brief prepared.');if(action==='filter')showToast('Showing Tokyo pilot · active records.');if(action==='run-match')showToast('Matching refreshed: 3 high-confidence suggestions.');if(action==='animal'||action==='animal-card')showToast('Animal registry editing is represented in this prototype.');if(action==='complete-all')showToast('Call session started with the oldest overdue item.')});
const tour=[['One customer history','The CRM connects source, consent, conversations, preferences and outcomes to one stable household record.'],['A living animal registry','Availability, care requirements, provenance and placement history stay connected to every animal.'],['Human-led matching','Fit scores surface promising pairs. Staff review suitability and retain the final decision.'],['Care after handover','Day-2, 14, 30 and 90 follow-ups turn outcomes into better future placements.']];function updateTour(){$('#tour-step').textContent=`${tourStep+1} / ${tour.length}`;$('#tour-title').textContent=tour[tourStep][0];$('#tour-copy').textContent=tour[tourStep][1];$('#tour-prev').disabled=tourStep===0;$('#tour-next').textContent=tourStep===tour.length-1?'Finish':'Next'}$('#tour-button').onclick=()=>{$('#tour').hidden=false;tourStep=0;updateTour()};$('.tour-close').onclick=()=>$('#tour').hidden=true;$('#tour-next').onclick=()=>{if(tourStep===tour.length-1)$('#tour').hidden=true;else{tourStep++;updateTour()}};$('#tour-prev').onclick=()=>{tourStep=Math.max(0,tourStep-1);updateTour()};
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#search').focus()}if(e.key==='Escape'){closeRecord();closeEnquiry();$('#tour').hidden=true}});
renderHouseholds();renderActions();renderOpportunities();renderAnimals();renderKanban();renderFollowups();
